from collections import defaultdict
from statistics import mean
from predict import HERE,E5,load
def num(v,n=2):return f"{v:.{n}f}".replace(".",",")
def percent(v):return num(v*100)
def main():
    result=load(HERE/"results.json");s=result["summaries"];cs=result["comparisons"]
    mode=load(E5/"throughput.json")
    ev=load(HERE/"outcomes.json.gz");q=defaultdict(dict)
    for r in ev:q[r["q"]][r["arm"]]=r
    both_miss=sum(not v["bm25/related"]["full_support"] and not v["e5/related"]["full_support"] for v in q.values())
    unique=sum(not v["bm25/related"]["full_support"] and not v["e5/related"]["full_support"] and v["rrf/related"]["full_support"] for v in q.values())
    lost=sum(v["bm25/related"]["full_support"] and v["e5/related"]["full_support"] and not v["rrf/related"]["full_support"] for v in q.values())
    success=s["rrf/related"]["fs_count"];e5=s["e5/related"]["fs_count"]
    inc=cs["e5/related"];within=cs["rrf/skip"]
    fc=load(HERE/"forecast-seal.json")["counts"]
    lines=["# Объединение лексического и плотного ранжирования для отбора памяти", "",
        f"При объединении BM25 и E5 правилом reciprocal rank fusion и приоритете пар вызова и результата агент получил полный комплект источников для **{success}/2 000 запросов ({percent(success/2000)}%)**. При том же приоритете один E5 дал {e5}/2 000; парная разность {num(100*inc['delta'])} п.п. Внутри одного и того же объединённого ранга приоритет пары изменил результат на {num(100*within['delta'])} п.п. относительно обычного добора по рангу. [Результаты](results.json) · [Поштучные наблюдения](outcomes.json.gz)", "",
        "## Все варианты при бюджете 2 048", "",
        "| Ранжировщик | Чтение памяти | Полные комплекты / 2 000 | FS, % | Покрытие эталонных символов, % | Плотность, % | Средний расход, токенов |",
        "|---|---|---:|---:|---:|---:|---:|"]
    for system,title in (("bm25","BM25"),("e5","E5"),("rrf","RRF")):
        for policy,label in (("prefix","Префикс"),("skip","Добор по рангу"),("related","Приоритет пары"),("value","Балл / √длины")):
            v=s[system+"/"+policy]
            lines.append(f"| {title} | {label} | {v['fs_count']} | {percent(v['full_support'])} | {percent(v['coverage'])} | {percent(v['density'])} | {num(v['tokens'])} |")
    lines.extend(["", "## Парные контрасты относительно RRF с приоритетом пары", "",
        "| Референс | Статус | Выигрыши / потери / совпадения | Разность FS, п.п. | 95% кластерный интервал, п.п. | Разность расхода, токенов |",
        "|---|---|---:|---:|---:|---:|"])
    for k,status in (("e5/related","Первичный"),("rrf/skip","Первичный"),("bm25/related","Описательный"),("rrf/value","Описательный")):
        d=cs[k];a,b=d["trajectory_bootstrap_ci95"]
        dt=s["rrf/related"]["tokens"]-s[k]["tokens"]
        lines.append(f"| {k} | {status} | {d['full_wins']} / {d['full_losses']} / {d['ties']} | {num(100*d['delta'])} | [{num(100*a)}; {num(100*b)}] | {num(dt)} |")
    lines.extend(["",f"В {both_miss} запросах оба отдельных ранжирования с приоритетом пары не доставили все источники. Из них гибрид доставил полный комплект в {int(unique)}. В {int(lost)} других запросах оба исходных ранжировщика доставили полный комплект по отдельности, а гибрид его потерял. Это описательный разбор всех исходов после эксперимента. [Замороженные прогнозы](forecast-seal.json)", "",
       "## Как устроено сравнение", "",
       f"Для 2 000 запросов в 1 207 траекториях проверены одинаковые {fc['candidate_instances']} вхождений кандидатов «запрос × узел» с точными идентификаторами, интервалами исходного текста и стоимостью. У каждой пары рангов одинаковый вес. Параметр k=60 взят из оригинальной работы; порядок задают позиции, начиная с 1. Отбор не читает координаты эталона. По каждому из четырёх вариантов записаны все выбранные узлы; для полного порядка записан контрольный хеш. Для {fc['queries_with_any_equal_rrf_score']} запросов в полном порядке встретились равные баллы; их порядок задан идентификатором узла. [Исходная работа по RRF](https://doi.org/10.1145/1571941.1572114) · [Протокол перед получением результатов E5](PROTOCOL_RU.md)", "",
       f"Расчёт RRF использует только упорядоченные списки от замороженного intfloat/e5-base-v2 ({mode['primary_precision']}, {mode['gpu']}) и BM25. Само слияние прошло на CPU. Время выполнения чтения, проверки координат, слияния и сохранения прогнозов приведено в журнале; оно исключает первоначальное кодирование GPU, извлечение BM25 и последующую оценку по эталону. Токены в таблицах — сумма цен выбранных узлов, перекрытия оплачиваются повторно. Ни расход на генерацию, ни результат ответа агента здесь не измерялись. [Журнал объединения](forecast-log.txt) · [Условия E5](../../isetrace_e5/throughput.json)", "",
       "Показатель Full Support принимает значение 1 при покрытии всех размеченных символов в нужных полях траектории. Расчёт сверялся с авторским скорером и отдельным объединением интервалов. 95% интервалы для обоих первичных контрастов получены при одном и том же парном бутстрепе целых траекторий; интервалы индивидуальные, без поправки за два контраста. Ранние результаты BM25 на той же выборке известны; первичный протокол и код объединения зафиксированы в отсутствие файла прогнозов и результатов полного E5. Превышение отдельного метода при таком сравнении относится к данной конфигурации. Статья об ISETrace сообщает 77,33% FS у обученного residual R-GCN и 50,50% у frozen provenance-unit Dense c исходным префиксом. RRF — известный метод агрегации, здесь он служит конкурентным контролем для чтения памяти. [Первичная публикация ISETrace](https://arxiv.org/html/2609.25913v3) · [Воспроизведение](REPRODUCE_RU.md)"])
    (HERE/"REPORT_RU.md").write_text("\n".join(lines)+"\n",encoding="utf8")
if __name__=="__main__":main()
